<span class="line"><span style="color:#ABB2BF;">        tf.keras.layers.</span><span style="color:#61AFEF;">AvgPool2D</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">pool_size</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">strides</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">),</span></span>
